    elif re.search('\\b(?:what amount|how much|which date|what date|what day|when is|when would)\\b', raw_normal):
     prefix = 'The pending terms for your ' + p['label'] + ' are ' + str(p['amount']) + ' on ' + p['date'] + '. '
    else:
     prefix = 'I do not have that information. '
   elif question == 'purpose':
    if s.get('verified') and (s.get('caller_status') != 'third_party'):
     prefix = 'I am calling from the collections team about a late payment. '
    else:
     prefix = "I am Freya Bank's digital assistant. I can explain more after the security check. "
   if s.get('caller_status') == 'third_party' and question in ('purpose', 'discount', 'unknown'):
    prefix = 'I am a digital assistant calling from Freya Bank, and we are recording this call. '
   if hardship_new and s.get('caller_status') != 'third_party':
    if not s.get('hardship'):
     prefix = 'I am sorry you are going through this. ' + prefix
    s['hardship'] = True
   if no_talk:
    s['talk_declines'] += 1
   if intent == 'deceased' and (not s.get('verified') or s.get('caller_status') == 'third_party'):
    finish('not_reached', 'deceased', 'I am sorry for your loss.')
   elif intent == 'wrong_number' and (not s.get('verified') or s.get('caller_status') == 'third_party'):
    finish('not_reached', 'wrong_number')
   elif human or (s.get('human_pending') and decision == 'reject'):
    if s['human_offered']:
     s['human_pending'] = False
     transfer('general')
    else:
     s['human_offered'] = True
     s['human_pending'] = True
     s['resume_prompt'] = s.get('prompt', '')
     tell(stage, 'Ask once: May I help you first? Do not require identity verification before an insisted request for a person.')
   elif stage == 'callback' and (not s.get('human_pending')):
    callback_turn(day, time_text, decision, intent, newly_third_party)
   elif s['talk_declines'] >= 2:
    finish('no_promise' if s.get('verified') else 'not_verified', 'refused' if s.get('verified') else 'declined')
   elif s.get('human_pending') and decision == 'accept' and (not proposal):
    s['human_pending'] = False
    if s.get('caller_status') == 'third_party':
     callback_turn(callback_day or day, callback_time or time_text, 'none', 'other', True)
    else:
     tell(stage, s.get('resume_prompt', 'Ask how you can help, without disclosing account information before verification.'))
   elif s.get('human_pending') and (not proposal):
    tell(stage, 'Ask whether you may help first. A question alone is not agreement. If the customer insists on a person, respect the request. Do not disclose account information before verification.')
   elif stage == 'locate':
    if caller == 'name_confirmed' or intent == 'name_yes':
     s['caller_status'] = 'customer_claimed'
     s['security_field'] = 'date_of_birth'
     tell('security', 'Ask only for the customer date of birth. Do not reveal the purpose of the call.')
    elif s['name_asks'] < 2:
     s['name_asks'] += 1
     ordinal = 'This is the second and final identification ask.' if s['name_asks'] == 2 else 'This is the first identification ask to the new speaker.'
     tell('locate', 'After answering any legitimate question, ask exactly: Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '? ' + ordinal + ' Do not disclose the purpose.')
    else:
     finish('not_reached', 'unclear')
   elif stage == 'support' and (not proposal) and (decision in ('accept', 'reject')):
    if decision == 'accept':
     transfer('support')
    else:
     finish('no_promise', 'hardship')
   elif hardship_new and (not proposal) and (s.get('caller_status') != 'third_party'):
    if not s.get('hardship'):
     prefix += 'I am sorry you are going through this. '
    s['hardship'] = True
    support()
   elif withdrawal_current and stage in ('negotiate', 'confirm', 'support') and p and (not p.get('recorded')):
    old_terms = pair(p['amount'], p['date'])
    if old_terms not in p['refused_offers']:
     p['refused_offers'].append(old_terms)
    p.update(confirmed='', readback='', terms_unresolved=False, unresolved_slot='', unprocessed={}, held_date_words='')
    persuade(p)
   elif stage in ('negotiate', 'confirm') and question == 'known' and re.fullmatch('(?:(?:you|can you|could you|please)\\s+)?(?:tell me\\s+)?(?:what is|what s|what would be)\\s+(?:the\\s+)?(?:least|minimum|smallest)(?:\\s+(?:amount|payment))?(?:\\s+(?:i can pay|i could pay|i must pay|required|allowed))?', raw_normal):
    tell(stage, 'Explain briefly that the minimum permitted amount is ' + str(p['floor']) + '. This answers a factual question; it is not refusal or a new proposal. If that amount has already been offered, refer to the existing offer without another persuasion pitch. Keep all pending terms and do not ask how much the customer can afford. Wait for their response.')
   elif financial_uncertain and stage in ('negotiate', 'confirm', 'support'):
    p['confirmed'] = ''
    if amount or day or full_unaffordable or missing_slot in ('amount', 'date', 'disposition') or (coverage == 'incomplete' and substantive):
     p['readback'] = ''
     p['terms_unresolved'] = True
    if amount:
     try:
      a = number(amount)
      if p['floor'] <= a <= p['past_due']:
       p['amount'] = a
     except Exception:
      pass
    if day:
     p['held_date_words'] = day
    if not p.get('unprocessed'):
     p['unprocessed'] = {'raw': raw_turn, 'amount': amount, 'date_words': day, 'amount_reference': amount_reference}
    else:
     if amount:
      p['unprocessed']['amount'] = amount
     if day:
      p['unprocessed']['date_words'] = day
    unresolved = missing_slot if missing_slot in ('amount', 'date', 'disposition') else 'decision'
    known_invalid_amount = False
    if amount and unresolved == 'date':
     try:
      known_invalid_amount = not p['floor'] <= number(amount) <= p['past_due']
     except Exception:
      pass
    if known_invalid_amount:
     p['terms_unresolved'] = False
     p['unresolved_slot'] = ''
     candidate(p, amount, day or 'vague')
    elif p.get('need_exact') and (not day) and (unresolved in ('date', 'decision')) and (not amount):
     p['terms_unresolved'] = False
     p['unresolved_slot'] = ''
     candidate(p)
    elif unresolved == 'date':
     if p.get('need_exact') and (not day):
      p['terms_unresolved'] = False
      p['unresolved_slot'] = ''
      candidate(p, amount)
     else:
      p['terms_unresolved'] = True
      p['unresolved_slot'] = 'date'
      p['need_exact'] = True
      tell('negotiate', 'Ask only which exact day the customer is proposing. Retain the independently understood amount and original proposal. Do not treat this unfinished or incompletely extracted proposal as refusal, consent, or inability to afford the full amount.')
    elif unresolved == 'amount':
     p['terms_unresolved'] = True
     p['unresolved_slot'] = 'amount'
     tell('negotiate', 'Ask for clarification of the amount the customer just proposed, retaining the date and other understood facts. Do not ask how much they can afford or replace their proposal with the earlier minimum.')
    elif unresolved == 'disposition':
     p['terms_unresolved'] = True
     p['unresolved_slot'] = 'disposition'
     tell('negotiate', 'Ask whether the customer means this overdue amount was already paid, disputes the account, or is proposing a future payment. Do not argue or take a promise until this distinction is clear. Retain the understood terms.')
    else:
     tell(stage, 'Ask a neutral clarification of the response to the immediately pending offer. Retain its terms and offer history; do not repeat the persuasion pitch, consume an attempt, or interpret missing evidence as agreement or refusal.')
   elif intent == 'paid' and s.get('verified') and (s.get('caller_status') != 'third_party'):
    finish('paid', '', 'Payments can take one business day to appear.')
   elif intent == 'dispute' and s.get('verified') and (s.get('caller_status') != 'third_party'):
    finish('no_promise', 'dispute', 'I understand that you dispute this account.')
   elif plan_request and s.get('caller_status') != 'third_party' and (not (proposal and (hardship_new or s.get('hardship')))):
    if s.get('hardship'):
     support()
    else:
     transfer('restructuring')
   elif stage == 'security':
    if intent in ('decline_security', 'reject') or ((intent == 'purpose' or question == 'purpose') and (not answer) and (not numeric_dob)) or no_talk:
     s['security_declines'] += 1
     if s['security_declines'] >= 2:
      finish('not_verified', 'declined')
     else:
      q = 'date of birth' if s['security_field'] == 'date_of_birth' else 'last four digits of the phone number on file'
      tell('security', 'Explain once that these questions protect the customer account. Then ask for the ' + q + '. Do not disclose the call purpose.')
    elif s.get('security_field') == 'date_of_birth' and _builder_unfinished_birth_year(raw_turn, answer or numeric_dob):
     tell('security', 'Ask the customer to finish or clarify the birth year and repeat the complete birth date with the month as a word. Do not guess a missing digit or reuse a year from an earlier answer. This incomplete answer is not a wrong-answer attempt.')
    elif answer or numeric_dob:
     field = s['security_field']
     good = True
     try:
      if field == 'date_of_birth':
       if numeric_dob:
        bits = re.findall('\\d+', numeric_dob)
        if len(bits) != 3 or len(bits[2]) != 4:
         raise ValueError('need day month year')
        answer = datetime.date(int(bits[2]), int(bits[1]), int(bits[0])).isoformat()
       else:
        answer = datetime.date.fromisoformat(answer).isoformat()
      else:
       good = bool(re.fullmatch('\\d{4}', answer))
     except Exception:
      good = False
     if good and s['wrong'] < 3 and (s.get('caller_status') != 'third_party') and (field == 'date_of_birth' or s.get('dob_pass')):
      vars['security_field'] = field
      vars['security_answer'] = answer
      request('verify')
     else:
      tell('security', 'Ask for clarification of the same security answer. For a birth date ask for the month as a word and the four-digit year; for the phone ask for exactly the last four digits. This parsing issue does not count as a wrong answer.')
    elif prefix:
     tell('security', s['prompt'])
    else:
     q = 'date of birth' if s['security_field'] == 'date_of_birth' else 'last four digits of the phone number on file'
     tell('security', 'Ask for the ' + q + ', one question only, without revealing the purpose of the call.')
   elif stage == 'service_wait':
    if s.get('caller_status') == 'third_party' and (callback_day or callback_time):
     callback_turn(callback_day, callback_time, decision, intent)
    elif decision == 'accept':
     retry = s.get('retry_kind', '')
     if retry in ('account', 'callback', 'transfer') and (not (retry == 'account' and s.get('caller_status') == 'third_party')):
      request(retry)
     elif s.get('caller_status') == 'third_party':
      callback_turn('', '', 'none', 'other', True)
     else:
      transfer('general')
    elif (decision == 'reject' or intent == 'done') and s.get('retry_kind') == 'callback':
     finish('not_reached', 'no_callback', 'No callback was scheduled.')
    elif decision == 'reject' or intent == 'done':
     s['retry_kind'] = ''
     tell('service_wait', 'Acknowledge that the action has not succeeded. Ask whether the customer would like help from a person instead; do not repeat the refused retry or claim success.')
    else:
     tell('service_wait', s['prompt'])
   elif stage == 'recorded':
    if intent == 'change_recorded' or amount or day:
     tell('recorded', 'Say a recorded promise cannot be changed or cancelled during this call. The customer can change it in the mobile app. Ask whether there is another question.')
    elif prefix:
     tell('recorded', 'Answer the legitimate question using only information actually available. Do not change or create another promise. Ask whether there is another question.')
    else:
     finish('promise')
   elif proposal:
    if hardship_new:
     if not s.get('hardship'):
      prefix += 'I am sorry you are going through this. '
     s['hardship'] = True
    s['human_pending'] = False
    unchanged_readback = False
    if stage == 'confirm' and decision == 'accept' and consent_current and (coverage == 'complete') and valid_candidate(p) and (not full_unaffordable):
     try:
      same_amount = not amount or number(amount) == number(p['amount'])
      same_date = not day or date_value(day) == p['date']
      unchanged_readback = same_amount and same_date and (p.get('readback') == pair(p['amount'], p['date']))
     except Exception:
      pass
    if unchanged_readback:
     p['confirmed'] = p['readback']
     p['consent_evidence'] = evidence
     p['consent_raw'] = raw_turn
     create(p)
    else:
     candidate(p, amount, day, too_much=full_unaffordable and (not amount))
   elif stage == 'support':
    if intent in ('done', 'no_talk') and raw_turn:
     finish('no_promise', 'hardship')
    else:
     tell('support', 'Briefly answer any genuine question without inventing terms. Ask neutrally whether the customer accepts or declines the already-pending support connection. Do not repeat the hardship pitch or make a payment persuasion attempt.')
   elif stage in ('negotiate', 'confirm'):
    if full_unaffordable:
     candidate(p, too_much=True)
    elif decision == 'reject':
     persuade(p)
    elif p.get('need_exact'):
     candidate(p, amount, day)
    elif decision == 'accept':
     if stage == 'confirm' and consent_current and valid_candidate(p) and (p.get('readback') == pair(p['amount'], p['date'])):
      p['confirmed'] = p['readback']
      p['consent_evidence'] = evidence
      p['consent_raw'] = raw_turn
      create(p)
     else:
      candidate(p)
    elif prefix or question == 'known':
     tell(stage, 'Answer the secondary question briefly from the pending product, amount, date and bank facts in state. Do not replay the offer or change its terms. If this is confirmation, ask neutrally whether the customer confirms the unchanged complete readback already spoken; otherwise clarify the response to the pending offer without another persuasion pitch.')
    elif explicit_nonanswer:
     tell(stage, 'Ask neutrally whether the customer accepts or declines the existing offer. Their reply is not refusal. Keep the pending amount, date and offer history unchanged; do not repeat a persuasion pitch, advance the offer or record a promise.')
    else:
     tell(stage, 'Ask neutrally for clarification of the response to the pending offer. Missing or uncertain extraction is neither acceptance nor refusal. Keep its terms, readback and offer history; do not advance persuasion or repeat an already-refused offer.')
   else:
    tell(stage, s.get('prompt', 'Ask whether the customer would like help from a person.'))
  if vars.get('next') in ('verify', 'account', 'callback', 'create', 'transfer'):
   s['carry_prefix'] = prefix
  vars['instruction'] = ('First say: ' + prefix + '\n' if prefix else '') + s.get('prompt', vars['instruction'])
 except Exception:
  s['pending'] = ''
  s['retry_kind'] = ''
  s['stage'] = 'service_wait'
  s['prompt'] = 'Say you do not have the information needed to continue this action. Do not claim it succeeded. Ask whether the customer would like help from a person. Do not disclose the call purpose to a third party or ask them security questions.'
  vars['instruction'] = s['prompt']
  vars['next'] = 'speak'
 vars['call_state'] = json.dumps(s)
 for key, empty_value in turn_defaults.items():
  vars[key] = empty_value
