pre_actions.pre_process_code:
import json
try:
    def object_value(value):
        try:
            value = json.loads(value) if isinstance(value, str) else value
            return value if isinstance(value, dict) else dict()
        except Exception:
            return dict()

    def succeeded(value):
        return str(value).lower() == 'true'

    s = object_value(vars.get('call_state', ''))
    data = object_value(vars.get('api_data', ''))
    products = s.get('products', {})
    products = list(products.values()) if isinstance(products, dict) else products
    products = [p for p in products if isinstance(p, dict)] if isinstance(products, list) else []
    pending = str(s.get('pending', ''))
    recorded = any(p.get('recorded') is True for p in products)
    recorded = recorded or succeeded(vars.get('create_promise_response.data.ok', False))
    recorded = recorded or (pending == 'create' and succeeded(data.get('ok', False)))
    transferred = s.get('transfer_success') is True
    transferred = transferred or succeeded(vars.get('transfer_to_agent_response.data.ok', False))
    transferred = transferred or (pending == 'transfer' and succeeded(data.get('ok', False)))
    scheduled = s.get('callback_recorded') is True
    scheduled = scheduled or succeeded(vars.get('schedule_callback_response.data.ok', False))
    scheduled = scheduled or (pending == 'callback' and succeeded(data.get('ok', False)))
    outcome = str(vars.get('outcome', ''))
    reason = str(vars.get('reason', ''))
    if recorded:
        outcome, reason = 'promise', ''
    elif scheduled:
        outcome, reason = 'not_reached', 'callback'
    transfer_reason = s.get('transfer_reason') or s.get('requested_transfer_reason') or vars.get('transfer_queue', '')
    transfer_reason = 'human' if transfer_reason == 'general' else transfer_reason
    if transferred and transfer_reason in ('human', 'support', 'restructuring'):
        outcome, reason = 'transferred', transfer_reason
    pairs = dict(promise=[''], paid=[''], transferred=['restructuring', 'human', 'support'], no_promise=['refused', 'hardship', 'dispute', 'service_error'], not_verified=['failed', 'declined'], not_reached=['callback', 'no_callback', 'wrong_number', 'deceased', 'unclear'])
    unsupported_success = (outcome == 'promise' and not recorded) or (outcome == 'transferred' and not transferred) or (outcome == 'not_reached' and reason == 'callback' and not scheduled)
    if outcome not in pairs or reason not in pairs.get(outcome, []) or unsupported_success:
        if s.get('verified') is True:
            outcome, reason = 'no_promise', 'service_error'
        elif s.get('stage') == 'security' and int(s.get('wrong', 0)) >= 3:
            outcome, reason = 'not_verified', 'failed'
        elif int(s.get('security_declines', 0)) >= 2 or int(s.get('talk_declines', 0)) >= 2:
            outcome, reason = 'not_verified', 'declined'
        else:
            outcome, reason = 'not_reached', 'unclear'
    body = dict(customer_id=str(vars.get('customer_id', '')), outcome=outcome)
    if outcome not in ('promise', 'paid'):
        body['reason'] = reason
    config['body'] = body
    vars['outcome'], vars['reason'] = outcome, reason
    vars['close_dispatched'] = 'yes'
except Exception:
    vars['close_dispatched'] = 'yes'

